  Hypothesis SPR : 0x7fff7f801800 <= bv_unsigned sp <= 0x7fffffffffc0.
  Hypothesis SP64 : bv_unsigned sp mod 64 = R.
  Hypothesis FR : 0x67f000 <= bv_unsigned Fb <= 0x7fffff800000.
  Hypothesis F64 : bv_unsigned Fb mod 64 = 0.
  Hypothesis DJ : bv_unsigned Fb + 64 <= bv_unsigned sp - 6144.
  Hypothesis INM : bv_unsigned Fb + 72 <= 0x7fff8000 \/ 0x10007fff8000 <= bv_unsigned Fb.
  Let E := Env (vals_ev vals) (blobs_ev []).
  Lemma sltu0_one : forall c, 0 < bv_unsigned sp + c < 2 ^ 64 ->
    alu64 ALU_SLTU (Z_to_bv 64 0) (alu64 ALU_ADD sp (Z_to_bv 64 c)) = Z_to_bv 64 1.
  Proof.
    intros c Hc. apply bv_eq. rewrite u_sltu64, u_add64, !u_lit64a. change (0 mod 2 ^ 64) with 0. change (1 mod 2 ^ 64) with 1.
    rewrite Zplus_mod_idemp_r. rewrite Z.mod_small by lia. destruct (Z.ltb_spec 0 (bv_unsigned sp + c)); [reflexivity | lia].
  Qed.
